import{z as A,x as s,o as e,c as d,q as r,j as n,D as E,d as o,s as i,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"商品的宏观策略","description":"","frontmatter":{"title":"商品的宏观策略","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mac-commodity-macro.md","filePath":"quant/mac-commodity-macro.md","lastUpdated":1791063341000}'),m={name:"quant/mac-commodity-macro.md"};function c(p,a,h,u,D,F){const t=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="商品的宏观策略" tabindex="-1">商品的宏观策略 <a class="header-anchor" href="#商品的宏观策略" aria-label="Permalink to &quot;商品的宏观策略&quot;">​</a></h1><div class="epigraph"><p>商品的宏观故事都要先过库存这一关：同一条需求新闻，库存低时是行情，库存高时只是头条。</p><footer>—— 据 Working, American Economic Review, 1949 与 Gorton, Hayashi &amp; Rouwenhorst, Review of Finance, 2013 整理</footer></div><p><a href="/quant/mac-fx-macro">上一课</a>把宏观之差落进汇率账户，并预告美元与商品的相关是共同因子的投影。象限表把商品放在过热与滞胀格（第二课），但商品自带一层别的资产没有的状态变量：库存与曲线。商品的宏观策略因此是两层状态之和——全球的增长通胀轴，加每个品种自己的库存轴。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>失效样本先摆出来：2008 年 7 月到 12 月，WTI 从 147 美元跌到 34 美元附近——增长塌下来时通胀预期跟着塌，「抗通胀资产」比股票跌得快。商品的麻烦是它不是一个资产类，而是一篮子各自出清的现货市场：收益要拆成现货、展期与抵押三腿（<a href="/quant/roll-yield">展期收益</a>），「抗通胀」只在通胀由需求或商品自身供给驱动的象限成立。缺口是把两层状态分开度量：宏观轴决定板块贝塔，库存轴决定每个品种的曲线形状与展期符号；混在一起，板块判断会被品种级的曲线运动淹没。</p><p><span class="marginnote">「展期收益」翻译成白话：期货会到期，多头必须不断把快到期的合约换成更远月的，这一换有赚有亏——贴水时像贱买贵卖，稳定小赚；升水时反过来，稳定小亏。长期持商品指数，收益里很大一块来自换约而非现货涨价。</span></p><h3 id="库存是品种级-regime" tabindex="-1">库存是品种级 regime <a class="header-anchor" href="#库存是品种级-regime" aria-label="Permalink to &quot;库存是品种级 regime&quot;">​</a></h3><p><a href="/quant/contango-backwardation">Contango 与 backwardation</a>描述曲线的相对位置，背后是库存：低库存支撑贴水，高库存把升水顶向全额持有成本——Working 的仓储逻辑。库存因此是商品自己的 regime 变量，第一课的框架在品种级重演：读库存的意外而非水平（<a href="/quant/inventory-curve">库存与曲线</a>），把基差当库存的影子变量做排序信号（<a href="/quant/commodity-roll-alpha">展期 alpha</a>）。</p><p><span class="marginnote">Gorton–Hayashi–Rouwenhorst（2013）在三十余个商品、近四十年月度库存数据上把基差的预测力归到可交割库存的低水平：基差是库存的影子，跳过库存直接读曲线，等于读影子不读人。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地分三步。第一步记账：现货、展期、抵押三腿分开，指数总收益里被机械滚仓窗吃掉多少展期要单独报（展期收益课的口径）。第二步两层信号：库存与基差在品种与到期之间排序，执行避开指数公开滚仓窗——那里的需求可预测、会被抢跑；宏观层把增长意外映射到工业金属与能源，通胀意外映射到广谱商品，美元当反向因子，板块内再做品种分散——单品种由天气、地缘与 OPEC 式供给冲击主导，分散是必须而不是装饰。第三步组合：按<a href="/quant/vol-targeting">波动目标</a>定各板块预算，与象限表对表——过热格加商品；滞胀格里商品是少数分子不受增长拖累的资产，但前提是通胀腿确实由商品驱动，工资与服务主导的通胀不会自动兑现成商品贝塔。</p>',11)),(e(),n(l,null,{default:E(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E5%BA%93%E5%AD%98%E6%84%8F%E5%A4%96%22%5D%20--%3E%20CUR%5B%22%E6%9B%B2%E7%BA%BF%E5%BD%A2%E7%8A%B6%EF%BC%9A%E8%B4%B4%E6%B0%B4%2F%E5%8D%87%E6%B0%B4%22%5D%0A%20%20CUR%20--%3E%20RS%5B%22%E5%B1%95%E6%9C%9F%E6%8E%92%E5%BA%8F%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20GR%5B%22%E5%A2%9E%E9%95%BF%E6%84%8F%E5%A4%96%22%5D%20--%3E%20SE%5B%22%E6%9D%BF%E5%9D%97%E6%98%A0%E5%B0%84%22%5D%0A%20%20IF%5B%22%E9%80%9A%E8%83%80%E6%84%8F%E5%A4%96%22%5D%20--%3E%20SE%0A%20%20US%5B%22%E7%BE%8E%E5%85%83%EF%BC%88%E5%8F%8D%E5%90%91%EF%BC%89%22%5D%20--%3E%20SE%0A%20%20SE%20--%3E%20PF%5B%22%E5%93%81%E7%A7%8D%E7%BB%84%E5%90%88%E4%B8%8E%E6%B3%A2%E5%8A%A8%E7%BC%A9%E6%94%BE%22%5D%0A%20%20RS%20--%3E%20PF%0A%20%20PF%20--%3E%20EX%5B%22%E9%81%BF%E5%BC%80%E6%8C%87%E6%95%B0%E6%BB%9A%E4%BB%93%E7%AA%97%E6%89%A7%E8%A1%8C%22%5D%0A%20%20EX%20--%3E%20AT%5B%22%E7%8E%B0%E8%B4%A7%2F%E5%B1%95%E6%9C%9F%2F%E6%8A%B5%E6%8A%BC%E4%B8%89%E8%85%BF%E5%BD%92%E5%9B%A0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[o("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"展期为什么是策略的核心而不是报表细节：静态持有商品指数，长期超额里展期贡献与现货贡献同阶，contango 里机械滚仓每年稳定漏血。展期 alpha 的机制是仓储理论：低库存时便利收益高，近月相对远月贵，多头收的是稀缺补偿，付钱的是需要即期供给的套保者——展期收益是对稀缺性的保险费。它与第二课「过热格商品占优」是同一枚硬币的两面：需求超预期首先击穿低库存品种的曲线，基差走强的截面排序本身就是宏观意外的微观成像，两层状态在机制上连通。",-1)),(e(),n(l,null,{default:E(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Low%5B%22%E5%BA%93%E5%AD%98%E4%BD%8E%22%5D%20--%3E%20CY%5B%22%E4%BE%BF%E5%88%A9%E6%94%B6%E7%9B%8A%E9%AB%98%22%5D%0A%20%20CY%20--%3E%20Near%5B%22%E8%BF%91%E6%9C%88%E7%9B%B8%E5%AF%B9%E8%BF%9C%E6%9C%88%E6%9B%B4%E8%B4%B5%22%5D%0A%20%20Near%20--%3E%20Back%5B%22%E6%9B%B2%E7%BA%BF%E8%B4%B4%E6%B0%B4%22%5D%0A%20%20Back%20--%3E%20Gain%5B%22%E5%A4%9A%E5%A4%B4%E6%BB%9A%E5%8A%A8%E6%94%B6%E6%AD%A3%E5%B1%95%E6%9C%9F%E6%94%B6%E7%9B%8A%22%5D%0A%20%20High%5B%22%E5%BA%93%E5%AD%98%E9%AB%98%22%5D%20--%3E%20LCY%5B%22%E4%BE%BF%E5%88%A9%E6%94%B6%E7%9B%8A%E4%BD%8E%22%5D%0A%20%20LCY%20--%3E%20Cont%5B%22%E6%9B%B2%E7%BA%BF%E5%8D%87%E6%B0%B4%22%5D%0A%20%20Cont%20--%3E%20Leak%5B%22%E6%BB%9A%E5%8A%A8%E6%AF%8F%E5%B9%B4%E7%A8%B3%E5%AE%9A%E6%BC%8F%E8%A1%80%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">数字感受升水曲线的漏血：若近月 100 美元、十二个月后 108 美元（年化升水约 8%），多头每年滚动换约就要拖累约 8%；换成贴水 8% 的曲线，同样滚动反而每年多收约 8%。同一桶油，曲线形状不同，年收益差出约 16 个百分点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>「通胀对冲」是条件的：需求驱动成立；供给驱动的滞胀里能源与农产品的冲击互不共线，广谱多头照样亏。仓储容量、交割地库存与挤仓能让曲线与宏观库存脱节（contango 课的口径）；政策储备改变的不是当期库存而是市场信念，读数要分账。主连连续行情不能用来回测展期现金流（展期 alpha 课的口径）。也不高估宏观轴的分辨率：金属与能源对增长意外的响应领先滞后各不相同，板块映射按月频校准，别按日频追。</p><p><span class="marginnote">常见误区：听到「通胀来了就买商品」。2008 年上半年通胀预期并不低，随后半年 WTI 仍从 147 美元跌到 34 美元附近——需求塌了，通胀预期跟着塌。商品抗的是「需求驱动的通胀」，不是名字里带通胀的一切行情。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>商品是两层状态之和：全球增长通胀轴定板块贝塔，库存轴定曲线与展期符号。</li><li>收益拆现货、展期、抵押三腿记账；指数机械滚仓的漏血单独报。</li><li>基差是库存的影子：排序读库存意外，执行避开公开滚仓窗。</li><li>「抗通胀」只在需求驱动通胀的象限成立；供给与政策冲击不共线。</li><li>出处：Working, AER, 1949；Gorton, Hayashi &amp; Rouwenhorst, Review of Finance, 2013；曲线与展期口径见<a href="/quant/contango-backwardation">Contango 与 backwardation</a>、<a href="/quant/roll-yield">展期收益</a>与<a href="/quant/commodity-roll-alpha">展期 alpha</a>。</li></ul>',6))])}const g=A(m,[["render",c]]);export{C as __pageData,g as default};
